import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin

class Page(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []
        self.links = []
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
        if tag == 'a' and not self.hidden:
            href = dict(attrs).get('href')
            if href:
                self.links.append(href)
    def handle_endtag(self, tag):
        if tag in ('script', 'style') and self.hidden:
            self.hidden -= 1
    def handle_data(self, data):
        if not self.hidden:
            value = ' '.join(data.split())
            if value:
                self.parts.append(value)

root = Path('products/distribution/sqlite-dev-tutorial')
needle = re.compile(r'artificial intelligence|generative AI|AI.generated|AI.assisted|affiliat|self.promotion|commercial content|spam|content policy|community guidelines', re.I)
link_pattern = re.compile(r'guidelines|code.of.conduct|/terms|/rules|ai.policy', re.I)
records = []
for filename, url in [('dev-terms.html', 'https://dev.to/terms'), ('dev-ai-tag.html', 'https://dev.to/t/ai')]:
    raw = (root / 'raw' / filename).read_bytes()
    page = Page()
    page.feed(raw.decode('utf-8', errors='replace'))
    passage_limit = 24 if filename == 'dev-terms.html' else 4
    passages = list(dict.fromkeys(' '.join(page.parts[max(0, index-1):index+2])[:600] for index, part in enumerate(page.parts) if needle.search(part)))[:passage_limit]
    pointers = sorted({urljoin(url, link) for link in page.links if link_pattern.search(link)})[:30]
    records.append({'source': url, 'sha256': hashlib.sha256(raw).hexdigest(), 'candidate_passages': passages, 'candidate_policy_links': pointers})
result = {'sources': records, 'scope': 'Offline extraction from two saved captures. Tag-page excerpts and links are discovery pointers. Read the original policy in context before drawing any permission conclusion.'}
out = root / 'director-policy-screen.json'
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(out), 'sources': [{'source': item['source'], 'passages': len(item['candidate_passages']), 'links': len(item['candidate_policy_links'])} for item in records]}))
